#include <iostream>
#include <utility>
template<typename T>
void otherFunction(T&& t) { std::cout << "In otherFunction: "; (t) = 10; std::cout << t << std::endl;}
template<typename T>
void forwarder(T&& t) { otherFunction(std::forward<T>(t)); }
int main() {
  int i = 5; 
  forwarder(i);       // Forwards lvalue, modifies original i
  forwarder(10);      // Forwards rvalue, temporary not modified
  return 0;
}
